# Figures (the R counterpart of plotly.py's basedatatypes.BaseFigure).
#
# A figure is a list(data = <list of traces>, layout = <go_layout>) classed
# "go_figure". Unlike plotly.py, figures are values: every function returns a
# new, modified figure, so calls can be chained with |>.
#
# Per-trace (add_scatter(), ...) and per-subplot (update_xaxes(), ...)
# functions are generated by codegen/figure.R into R/zz-gen-figure.R and call
# the helpers here.

#' Create a figure
#'
#' A figure holds a list of traces (`data`) and a `layout`. Everything is
#' validated against the plotly.js schema. Printing a figure renders it as an
#' htmlwidget.
#'
#' @param data A trace (e.g. from [go_scatter()]), a list of traces, or a
#'   figure (or a list with `data` and `layout` elements) to copy. Traces may
#'   be graph objects or named lists with a `type` element.
#' @param layout A [go_layout()] object or a named list of layout properties.
#' @param skip_invalid If `TRUE`, silently drop invalid properties instead of
#'   raising an error.
#' @return A `go_figure` object.
#' @seealso [add_trace()], [update_layout()], [update_traces()]
#' @export
#' @examples
#' fig <- go_figure(
#'   data = go_scatter(x = 1:3, y = c(2, 1, 3)),
#'   layout = go_layout(title = "A figure")
#' )
#' fig <- fig |>
#'   add_scatter(x = 1:3, y = c(3, 2, 1), mode = "markers") |>
#'   update_layout(xaxis_title = "x")
#' if (interactive()) print(fig)
go_figure <- function(data = NULL, layout = NULL, skip_invalid = FALSE) {
  if (inherits(data, "go_figure") || (is.list(data) && !is.data.frame(data) && !inherits(data, "plotly_obj") &&
                                      !is.null(names(data)) && all(names(data) %in% c("data", "layout")))) {
    src <- unclass(data)
    data <- src$data
    layout <- layout %||% src$layout
  }
  new_figure(validate_data(data, skip_invalid), validate_layout(layout, skip_invalid))
}

new_figure <- function(data, layout) structure(list(data = data, layout = layout), class = "go_figure")

check_figure <- function(fig) {
  if (!inherits(fig, "go_figure")) {
    stop("Expected a go_figure object, not ", value_type(fig), call. = FALSE)
  }
  invisible(fig)
}

#' @export
`$<-.go_figure` <- function(x, name, value) set_figure_part(x, name, value)

#' @export
`[[<-.go_figure` <- function(x, i, value) set_figure_part(x, i, value)

set_figure_part <- function(fig, name, value) {
  fig <- unclass(fig)
  if (identical(name, "data")) {
    fig$data <- validate_data(value)
  } else if (identical(name, "layout")) {
    fig$layout <- validate_layout(value)
  } else {
    stop("A figure has only `data` and `layout` elements", call. = FALSE)
  }
  new_figure(fig$data, fig$layout)
}

#' Print or knit a figure
#'
#' Printing a figure renders it with [plotly_widget()]: in the RStudio
#' viewer, a browser, or inline in R Markdown and Quarto documents.
#'
#' @param x A `go_figure` object.
#' @param ... Passed on to the htmlwidget print or knit_print method.
#' @return `x`, invisibly, for `print()`.
#' @export
print.go_figure <- function(x, ...) {
  print(plotly_widget(x), ...)
  invisible(x)
}

#' @rdname print.go_figure
#' @param options Chunk options (from knitr).
#' @exportS3Method knitr::knit_print
knit_print.go_figure <- function(x, ..., options = NULL) {
  knitr::knit_print(plotly_widget(x), ..., options = options)
}

# Adding traces -----------------------------------------------------------------

#' Add traces to a figure
#'
#' @param fig A `go_figure` object.
#' @param trace A trace: a graph object such as [go_scatter()], or a named
#'   list with a `type` element (default `"scatter"`).
#' @param data A list of traces.
#' @return The modified figure.
#' @seealso The generated `add_<trace type>()` functions, e.g. [add_scatter()].
#' @export
#' @examples
#' go_figure() |>
#'   add_trace(go_scatter(x = 1:3, y = 1:3)) |>
#'   add_traces(list(list(type = "scatter", y = 3:1), go_scatter(y = c(2, 2, 2))))
add_trace <- function(fig, trace) {
  check_figure(fig)
  new_figure(c(fig$data, list(validate_trace(trace))), fig$layout)
}

#' @rdname add_trace
#' @export
add_traces <- function(fig, data) {
  check_figure(fig)
  new_figure(c(fig$data, validate_data(data)), fig$layout)
}

# Updating ---------------------------------------------------------------------

# Recursively update graph object `obj` (schema key `key`) with `patch`.
# Properties that are compound objects are merged unless `overwrite` is TRUE;
# everything else is replaced. NULL removes a property. Names may use magic
# underscores (marker_size). The result is validated.
update_object <- function(obj, key, patch, overwrite = FALSE) {
  entry <- get_validator(key)
  obj <- if (is.null(obj)) list() else unclass(obj)
  patch <- unclass(patch)
  for (name in names(patch)) {
    val <- patch[[name]]
    ck <- child_key(key, name)
    if (is.na(ck)) {
      if (!is.null(entry$trace_type) && name == "type") next
      obj <- set_magic_property(obj, key, entry, name, val)
      next
    }
    child <- get_validator(ck)
    mergeable <- !overwrite && child$superclass %in% c("CompoundValidator", "TitleValidator") &&
      is.list(val) && is.list(obj[[name]])
    obj[name] <- list(if (mergeable) update_object(obj[[name]], ck, val, overwrite) else val)
  }
  obj <- obj[!vapply(obj, is.null, logical(1))]
  out <- vc_compound(obj, key, entry)
  if (!is.null(entry$trace_type)) out <- add_trace_type(out, entry$trace_type)
  out
}

combine_patch <- function(patch, dots) {
  if (!is.null(patch) && (!is.list(patch) || is.null(names(patch)))) {
    stop("`patch` must be a named list or graph object", call. = FALSE)
  }
  if (length(dots) && (is.null(names(dots)) || any(!nzchar(names(dots))))) {
    stop("All properties in `...` must be named", call. = FALSE)
  }
  c(unclass(patch), dots)
}

#' Update a figure's layout
#'
#' Updates layout properties, merging nested objects (e.g. `xaxis`) with any
#' existing values unless `overwrite = TRUE`. Properties can be given in
#' `patch`, in `...`, or both; `...` is applied last. Names may use "magic
#' underscores": `xaxis_title_text = "x"` is the same as
#' `xaxis = list(title = list(text = "x"))`.
#'
#' @param fig A `go_figure` object.
#' @param patch A named list or [go_layout()] object of updates.
#' @param ... Further named updates.
#' @param overwrite If `TRUE`, replace nested objects instead of merging.
#' @return The modified figure.
#' @export
#' @examples
#' go_figure() |>
#'   update_layout(title = "Title", xaxis = list(range = c(0, 10))) |>
#'   update_layout(xaxis_title = "x", yaxis = list(type = "log"))
update_layout <- function(fig, patch = NULL, ..., overwrite = FALSE) {
  check_figure(fig)
  layout <- update_object(fig$layout, "layout", combine_patch(patch, list(...)), overwrite)
  new_figure(fig$data, layout)
}

# Selecting ---------------------------------------------------------------------

# Look up a property by plain or magic-underscore name; NULL if absent.
get_prop <- function(obj, name) {
  obj <- unclass(obj)
  if (name %in% names(obj)) return(obj[[name]])
  pos <- gregexpr("_", name, fixed = TRUE)[[1L]]
  for (p in pos[pos > 0L]) {
    head <- substr(name, 1L, p - 1L)
    if (is.list(obj[[head]])) {
      found <- get_prop(obj[[head]], substr(name, p + 1L, nchar(name)))
      if (!is.null(found)) return(found)
    }
  }
  NULL
}

plain_value <- function(x) {
  if (is.list(x)) {
    x <- unclass(x)
    x[] <- lapply(x, plain_value)
  } else if (inherits(x, "AsIs")) {
    x <- unclass(x)
  }
  x
}

# plotly.py's _selector_matches: NULL matches everything, a string matches
# the trace type, a named list matches when every element equals the
# object's property, and a function is called with the object.
selector_matches <- function(obj, selector) {
  if (is.null(selector)) return(TRUE)
  if (is.function(selector)) return(isTRUE(selector(obj)))
  if (is.character(selector) && length(selector) == 1L) selector <- list(type = selector)
  if (is.list(selector) && (length(selector) == 0L || !is.null(names(selector)))) {
    for (name in names(selector)) {
      val <- get_prop(obj, name)
      if (is.null(val)) return(FALSE)
      if (!isTRUE(all.equal(plain_value(val), plain_value(selector[[name]]), check.attributes = FALSE))) {
        return(FALSE)
      }
    }
    return(TRUE)
  }
  stop("`selector` must be NULL, a named list, a string, a function or (for traces) trace indices",
       call. = FALSE)
}

trace_indices <- function(fig, selector) {
  n <- length(fig$data)
  if (is.numeric(selector)) {
    if (any(selector < 1 | selector > n)) stop("Trace index out of range: the figure has ", n, " trace(s)", call. = FALSE)
    return(as.integer(selector))
  }
  which(vapply(fig$data, selector_matches, logical(1), selector = selector))
}

#' Select, update or modify traces
#'
#' `select_traces()` returns the traces matching `selector`.
#' `update_traces()` updates their properties like [update_layout()] does.
#' `for_each_trace()` replaces each one with the result of `fn`.
#'
#' @param fig A `go_figure` object.
#' @param selector Which traces to use: `NULL` (all), a trace type such as
#'   `"scatter"`, trace indices, a named list of property values that must
#'   all match (names may use magic underscores, e.g.
#'   `list(marker_color = "red")`), or a function that takes a trace and
#'   returns `TRUE` or `FALSE`.
#' @param patch A named list of property updates.
#' @param ... Further named updates.
#' @param overwrite If `TRUE`, replace nested objects instead of merging.
#' @param fn A function that takes a trace and returns the modified trace.
#'   If it returns anything other than a list, the trace is left unchanged.
#' @return `select_traces()` returns a list of traces; the others return the
#'   modified figure.
#' @export
#' @examples
#' fig <- go_figure() |>
#'   add_scatter(y = 1:3, name = "a") |>
#'   add_scatter(y = 3:1, name = "b", mode = "markers")
#' select_traces(fig, list(name = "b"))
#' fig <- update_traces(fig, marker_size = 12, selector = list(mode = "markers"))
#' fig <- for_each_trace(fig, function(tr) {
#'   tr$name <- toupper(tr$name)
#'   tr
#' })
select_traces <- function(fig, selector = NULL) {
  check_figure(fig)
  fig$data[trace_indices(fig, selector)]
}

#' @rdname select_traces
#' @export
update_traces <- function(fig, patch = NULL, selector = NULL, ..., overwrite = FALSE) {
  check_figure(fig)
  patch <- combine_patch(patch, list(...))
  data <- fig$data
  for (i in trace_indices(fig, selector)) {
    data[[i]] <- update_object(data[[i]], data[[i]]$type, patch, overwrite)
  }
  new_figure(data, fig$layout)
}

#' @rdname select_traces
#' @export
for_each_trace <- function(fig, fn, selector = NULL) {
  check_figure(fig)
  data <- fig$data
  for (i in trace_indices(fig, selector)) {
    res <- fn(data[[i]])
    if (is.list(res)) data[[i]] <- validate_trace(res)
  }
  new_figure(data, fig$layout)
}

# Layout subplots (xaxis, yaxis2, ...) ---------------------------------------------

# Names of the layout subplot objects of a given type, in numeric order. The
# base object (e.g. "xaxis") is always included, as in plotly.py where it
# always exists.
subplot_names <- function(layout, prefix) {
  nms <- grep(paste0("^", prefix, "([1-9][0-9]*)?$"), names(layout), value = TRUE)
  nms <- union(prefix, nms)
  num <- suppressWarnings(as.integer(sub(prefix, "", nms, fixed = TRUE)))
  nms[order(ifelse(is.na(num), 1L, num))]
}

select_layout_subplots <- function(fig, prefix, selector = NULL) {
  check_figure(fig)
  key <- paste0("layout.", prefix)
  objs <- lapply(subplot_names(fig$layout, prefix), function(n) {
    fig$layout[[n]] %||% validate_coerce(list(), key)
  })
  names(objs) <- subplot_names(fig$layout, prefix)
  objs[vapply(objs, selector_matches, logical(1), selector = selector)]
}

update_layout_subplots <- function(fig, prefix, patch, selector, dots, overwrite) {
  patch <- combine_patch(patch, dots)
  key <- paste0("layout.", prefix)
  layout <- unclass(fig$layout)
  for (n in names(select_layout_subplots(fig, prefix, selector))) {
    layout[[n]] <- update_object(layout[[n]], key, patch, overwrite)
  }
  new_figure(fig$data, as_graph_object(layout, get_validator("layout")))
}

for_each_layout_subplot <- function(fig, prefix, fn, selector) {
  key <- paste0("layout.", prefix)
  layout <- unclass(fig$layout)
  objs <- select_layout_subplots(fig, prefix, selector)
  for (n in names(objs)) {
    res <- fn(objs[[n]])
    if (is.list(res)) layout[[n]] <- validate_coerce(res, key)
  }
  new_figure(fig$data, as_graph_object(layout, get_validator("layout")))
}
